lib_src='''def components(grid, background=0):
    """The connected (4-neighbor) same-color components as (color, cells) pairs, ignoring the background."""
    h, w = len(grid), len(grid[0])
    seen = set(); comps = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] != background and (i, j) not in seen:
                col = grid[i][j]; stack = [(i, j)]; cells = []; seen.add((i, j))
                while stack:
                    y, x = stack.pop(); cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == col and (ny, nx) not in seen:
                            seen.add((ny, nx)); stack.append((ny, nx))
                comps.append((col, cells))
    return comps

def norm_shape(cells):
    """A tuple of cells translated so its bounding box starts at (0, 0), sorted."""
    ys = [y for y, _ in cells]; xs = [x for _, x in cells]
    y0, x0 = min(ys), min(xs)
    return tuple(sorted((y - y0, x - x0) for y, x in cells))

def unify_shapes(grid, key=lambda cols: max(cols)):
    """Recolor every repeated shape (by color component) so each shape group takes key of its colors; unique shapes keep theirs."""
    groups = {}
    for col, cells in components(grid):
        groups.setdefault(norm_shape(cells), []).append((col, cells))
    out = [row[:] for row in grid]
    for shape, members in groups.items():
        if len(members) > 1:
            target = key([c for c, _ in members])
            for c, cells in members:
                if c != target:
                    for y, x in cells: out[y][x] = target
    return out
